INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Days Motel', 'In the doomsday Hotel, you can experience the hard life in the waste Land World. Stick to hope in motel-based doomsday shelters and fight survival challenges such as hunger, thirst and lack of energy. Risking their lives to collect supplies, develop and build hotel shelters. Do everything possible to survive the cataclysmic world.' FROM games WHERE igdb_id = 114598 ON CONFLICT (game_id, language_code) DO NOTHING;
