INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spirit-of-the-north', 107141, '2019-11-13', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ewy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbja.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spirit of the North', '"Spirit of the North is a single player, 3rd-person adventure game inspired by the breathtaking and mysterious landscapes of Iceland. The story takes root from various pieces of Nordic folklore. The game is unique in that it purposefully has no dialog or narrative. Players must breathe in their surroundings to solve various puzzles and speculate the meaning of a lost ancient civilization. Play as an ordinary red fox who’s story becomes entwined with the guardian of the Northern Lights, a female spirit fox. As you journey over the mountains and under red stained skies you’ll discover more about your companion and a land left in ruin."' FROM games WHERE igdb_id = 107141 ON CONFLICT (game_id, language_code) DO NOTHING;
