INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Wolf Chaos XD', 'The country is in peril as President Michael Wilson defends the nation against a full-scale rebellion lead by Vice-President Richard Hawk and the mechanized legions he commands. As the 47th President of the United States, it is your sworn duty to take your country back by any means necessary and end this unjust coup d''etat! Battle in your advanced mech - armed to the teeth - across iconic American landscapes including the Brooklyn Bridge, the Grand Canyon, and the front steps of the White House.' FROM games WHERE igdb_id = 103304 ON CONFLICT (game_id, language_code) DO NOTHING;
