INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'When the Darkness comes', 'Taking around an hour on the first play-through, "When The Darkness Comes" feels like you''re wandering around a glitchy hard drive full of abstract dreams and beautiful nightmares. The narrator initially makes it feel like a comedic game, but it soon starts to take a darker tone as you travel down the bizarre broken rabbit hole that explores the darkest themes of the human mind.' FROM games WHERE igdb_id = 114420 ON CONFLICT (game_id, language_code) DO NOTHING;
