INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Timothy and the Mysterious Forest', 'Timothy and the Mysterious Forest is a mix of old-school Game Boy graphics, meta-narrative, stealth system and action combat with an high difficulty level. Elements from adventure/exploration games are mixed with puzzle and stealth: exploration, reading and keeping a slow pace is the best tactic. Multiple endings!' FROM games WHERE igdb_id = 122144 ON CONFLICT (game_id, language_code) DO NOTHING;
