INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tranquility Base Mining Colony: The Moon - Explorer Version', 'Wanna'' walk on the Moon?Tranquility Base Mining Colony: The Moon - Explorer Version, is an open-world game area that encompasses about 17,000 sq kilometers of lunar terrain, around the Apollo 11 landing site. We''ve taken topographic data from NASA''s Lunar Reconnaissance Laser Altimeter (LOLA) which is mounted on the Lunar Reconnaissance Orbiter (LRO) to create this 3d map for you to explore.' FROM games WHERE igdb_id = 106324 ON CONFLICT (game_id, language_code) DO NOTHING;
