INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xeno-time-inception', 104938, '2019-08-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/m81ehtvywo49n31rlso7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/pyyvf0ymwyc5js7hxjau.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xeno Time Inception', 'Xeno Time Inception is a unique indie sci-fi solo FPS. Play as Carl and experience his adventures through a world of altered temporality and boundaries. Forget everything you know or expect about time and dive into new parallel worlds. You need to save the world from disruption and total disaster. To do so you’ll have to discover the truth, close temporal portals and save different personalities and thus put back in place the course of time.' FROM games WHERE igdb_id = 104938 ON CONFLICT (game_id, language_code) DO NOTHING;
