INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '60 Second History', '60 Second History is a game where you play a series of minigames to create your own messed up timeline. History changes depending on how you play the game, from little cosmetic details to entire separate branches of history with their own unique minigames. After six ten-second minigames, you''ll be shown an ending that tells you what your version of the future is like.' FROM games WHERE igdb_id = 332212 ON CONFLICT (game_id, language_code) DO NOTHING;
