INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dear Diary', 'Plunge into the story of a guy who keeps a personal diary and writes everything that happens to him. Follow along as he recounts how he met a girl in the forest and secretly watched her bathe naked in a lake. Enjoying the view from behind bushes, his pleasure turns to suspense when the girl senses she''s being watched. Players have to play the game to discover what happens next.' FROM games WHERE igdb_id = 118084 ON CONFLICT (game_id, language_code) DO NOTHING;
