INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soulash', 'Soulash is a fantasy roguelike where the player takes on the role of a forgotten god set on destroying the world. The main features of the game are consistent open world, perma-death, turn-based tactical combat, a crafting system and a unique inventory system where every item is temporary.' FROM games WHERE igdb_id = 118457 ON CONFLICT (game_id, language_code) DO NOTHING;
