INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('basketball-club-story', 150265, '2019-06-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8uys.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9sr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Basketball Club Story', 'Make your very own world-class basketball team! Specialize in one skill? Be a jack-of-all-trades? Or something in between? Create your own basketball team, recruit a cast of zany players, and compete against other teams. It''s up to YOU to coach them to victory! Plus, build facilities for your clubhouse for your players and visitors to enjoy. Mix, match, and position them however you like! Sign with sponsors to gain impressive monetary support. Foster them alongside the rest of your team for even more rewards! Don''t forget to connect with your local fans through community outreach. The more they learn about basketball, the more passionate they''ll become! With the help of your players, sponsors, and spectators, you''ll create the world''s best basketball team! Try searching for "Kairosoft" to see all of our games!!' FROM games WHERE igdb_id = 150265 ON CONFLICT (game_id, language_code) DO NOTHING;
