INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disco Elysium', 'Disco Elysium is a role-playing game developed and published by ZA/UM. It is set in the fictional city of Revachol, where players assume the role of an amnesiac detective investigating a murder case. The game emphasises dialogue and skill-based choices, with character attributes represented by internal voices that influence decisions and interactions. Its narrative explores themes of politics, philosophy, and personal identity, and it is known for its unconventional gameplay and deep storytelling.' FROM games WHERE igdb_id = 26472 ON CONFLICT (game_id, language_code) DO NOTHING;
