INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic Monster World', 'Jurassic Monster World is a mobile game like you''ve never seen before. Battle metal-plated monster dinos in a post-apocalyptic world! A synchronized 5x5 PvP free-to-play action shooter with different modes! Control beasts on land or in the sky, fully mechanized, augmented or organic: the choice is yours! Tame and command dozens of blood-thirsty metal hunters ready to destroy anything in their paths to win!' FROM games WHERE igdb_id = 141508 ON CONFLICT (game_id, language_code) DO NOTHING;
