INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Waltz of the Wizard', 'Delve into a meticulously crafted fantasy world, greatly expanded with major updates since the original release and now includes an all new Screen Mode! Waltz of the Wizard includes hours of rich fantasy content, cutting-edge VR features and many curious secrets. Experience magical powers in a world inspired classical fantasy fiction! Combine arcane ingredients into a boiling cauldron with the help of an ancient talking skull, unleashing spells upon a fully interactive and mysterious world. Use blazingly fast voice interactions to wield magic, talk to characters or team up with a friend in local co-op on a screen with controller/keyboard and a VR headset.' FROM games WHERE igdb_id = 119994 ON CONFLICT (game_id, language_code) DO NOTHING;
