INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inops', 'Explore the shadowy Mine, twisty Jungle and extra-terrestrial Elect-City but be careful of lurking dangers. Escape traps, solve puzzles and dodge enemies using the Inops ability to split into many little creatures or join into one big Inop whenever you wish. Use the environment to your advantage by using unique intractable components whilst guiding the Inops simultaneously. Get to the end of each level and save as many Inops as you can to avoid being lonesome.' FROM games WHERE igdb_id = 114177 ON CONFLICT (game_id, language_code) DO NOTHING;
