INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ongeki Plus', 'Ongeki Plus is an expanded version of the original Ongeki arcade rhythm game, released in Japan in 2019. It introduced a mission system for earning rewards, daily login bonuses, and more flexible story progression by removing chapter order restrictions. The GP system was updated with multiple play modes, and item use (like Jewels) was expanded for better in-game benefits.' FROM games WHERE igdb_id = 154646 ON CONFLICT (game_id, language_code) DO NOTHING;
