INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donensbourgh - Medieval RPG', 'Donensbourgh is a medieval RPG game single player in first person, made with UE4. The progress is based on skills with actions like crafting, farming, trading, cooking, talking, digging, fishing, feeding, ... There are no spells, combats or deaths involved. It''s a another kind of medieval game. Just enjoy living in medieval era with realistic environments, tools and buildings.' FROM games WHERE igdb_id = 123120 ON CONFLICT (game_id, language_code) DO NOTHING;
