INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Rangers: Battle for the Grid - Collector''s Edition', 'A modern take on the 25 year franchise, Power Rangers: Battle for the Grid showcases stunning graphics with vivid details. Pit current and classic Rangers and villains like never before in team battles. Test your skills online against friends and players from around the world for endless replayability. A streamlined combat system welcomes newcomers with simplified controls while maintaining depth for the most dedicated competitor to learn and master.' FROM games WHERE igdb_id = 119069 ON CONFLICT (game_id, language_code) DO NOTHING;
