INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hat World: New Testament', 'An indie RPG developed primarily by a solo developer using RPG Maker VX. The player can select one of six main characters in a multiverse of mysterious worlds created through the power of hats. The game lets you explore beautiful side-scrolling maps and take part in fast-paced turn-based battles, with non-linear progression, sidequests, and lots of customization. Oh, and there are also cute girls in big hats.' FROM games WHERE igdb_id = 229186 ON CONFLICT (game_id, language_code) DO NOTHING;
