INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imperator: Rome', '"Paradox Development Studio returns to ancient history with Imperator: Rome, a new title set around the growth of Roman power in a threatening Mediterranean. Unify Italy and then the world under the eagles of your legions. Or rule an Eastern monarchy with claims to the mantle of Alexander. Slaves, barbarians and war elephants bring the distant past to life in Imperator: Rome. Can you be a Caesar?"' FROM games WHERE igdb_id = 102060 ON CONFLICT (game_id, language_code) DO NOTHING;
