INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operencia: The Stolen Sun', 'Zen Studios’ modern homage to classic first-person dungeon-crawlers takes you to the land of Operencia, an unconventional fantasy world inspired by a faraway land referenced in countless Central European folktales. An old-school turn-based battle system combines with inspiration from unexplored mythology to offer an RPG experience that feels unique yet also familiar.' FROM games WHERE igdb_id = 113212 ON CONFLICT (game_id, language_code) DO NOTHING;
