INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NASCAR Heat 4', 'NASCAR Heat 4 is the official video game of NASCAR, featuring the 2019 Monster Energy NASCAR Cup Series, NASCAR Xfinity Series, NASCAR Gander Outdoors Truck Series and fan-favorite, the Xtreme Dirt Tour. Career mode enhancements, updated visuals, and new engine audio immerses players in the race. The new track map and unlockable paint schemes, combined with new AI controls, drafting features, and updated user interface gives players a more authentic feel for the action. Compete across 38 tracks against the 150+ official NASCAR teams and drivers as you race for the championship!' FROM games WHERE igdb_id = 120487 ON CONFLICT (game_id, language_code) DO NOTHING;
