INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adrenaline Rush: Miami Drive', 'Find yourself smack in the middle of a police chase! Get a taste of adrenaline and thrills! It’s all waiting for you in ‘Adrenaline Rush - Miami Drive’. Driving in the wrong direction, crackups and spectacular crashes, dizzying speed ‒ all this against the incredible backdrop of the night city and highways! Your task is to escape from your pursuers, collect coins and smash into as many vehicles as possible. And all this with a minimum of rules and a maximum of fun! Play on Joy-Con or using motion controls! Let''s go!' FROM games WHERE igdb_id = 122735 ON CONFLICT (game_id, language_code) DO NOTHING;
