INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game of Thrones: Winter is Coming', 'Game of Thrones Winter is Coming picks up right after the death of Lord Eddard Stark. You’ll play the part of an ambitious Westerosi lord determined to stop the endless fighting between the Seven Kingdoms and save people from endless war, which doesn’t sound like many Westerosi lords we know. Along the way, you’ll come into contact with characters from the show and get a chance to recruit them to your cause.' FROM games WHERE igdb_id = 114007 ON CONFLICT (game_id, language_code) DO NOTHING;
