INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Case Files: Ravenhearst Unlocked', 'Eipix delves deeper into the past as you find yourself trapped in the very cell that the Dalimars once occupied. Can you stop Alister before he sacrifices everything - and everyone - in his maniacal quest for immortality? Or will his menacing granddaughters stand in your way? You''ll love the loads of mini-games embedded throughout this adventure. The HOPs are full of variety, with silhouette, listed, interactive, and more to choose from!' FROM games WHERE igdb_id = 84144 ON CONFLICT (game_id, language_code) DO NOTHING;
