INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('skybolt-zack', 109028, '2019-11-07', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4tjm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6h7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skybolt Zack', 'Skybolt Zack delivers a unique gaming experience - all the fun and excitement of an arcade platformer married with the feel of a Japanese rhythm game. Ditching the pixel perfect precision of traditional platformers, Skybolt Zack introduces new mechanics that are equally challenging but fresh and exciting. Players will have their dexterity and quick thinking tested in equal measure. Reacting to the enemies on screen, players must Dash and Rocket Punching and Charge Attack their way from enemy to enemy by colour matching the buttons on the gamepad to the enemies on screen before bouncing off of them to reach new heights. The higher the player climbs, the more difficult the game gets, but the more rewarding it becomes...
