INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gerty', 'Gerty is a top-down rogue-lite twin-stick shooter with a fully destructible environment. Carve your own path through replayable procedurally generated levels and create tactically advantageous situations to eliminate the alien threat in intense, tough but fair, action-packed gameplay. Mine Juice crystals to upgrade your gear, discover alien structures, and eliminate the source of the alien threat in singleplayer or local co-op mode.' FROM games WHERE igdb_id = 110587 ON CONFLICT (game_id, language_code) DO NOTHING;
