INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('20-minute-metropolis', 124263, '2019-09-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co267m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1xgv.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '20 Minute Metropolis', 'Centuries after a nuclear war, you''re charged with rebuilding civilization. It''s your job to create a functioning city in 20 years (that''s 20 minutes realtime!). Begin by laying roads to bring food to your people, then build apartments to give them somewhere to live. Extend your reach by cutting through forest and—oops, your apartments have filled up with waste, so you''ll have to build a landfill. Where was I? Cut through forest to get to ancient skyscrapers, which you''ll mine for metals and plastics—you''re an ace recycler! Oops, your people have deforested the area. Expand! Set up a water turbine and energy transmitters. And some parks! Now you''re cooking. Build a dozen high rises and more parks. Aaand you''re out of time. How''d you do? You beat your high score! Now, how can you top it?' FROM games WHERE igdb_id = 124263 ON CONFLICT (game_id, language_code) DO NOTHING;
