INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-80s-world', 116013, '2019-04-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coajng.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super 80s World', 'Rewind time to 1980 in this mobile platformer, where you save the decade by collecting old-school memorabilia. Dr. Noid Wormser hates the ''80s and vowed to erase the decade. Emptying the pop culture of his tortured youth from the recycle bin of history. Only one man, stuck in the decade forever, has the power to stop him. That man is Dan Camaro. Dan. Camaro. Bounce, flip and slide your way through the decade. Each year is a different world, from coin-operated arcades to the neon glow of Miami Beach. Many obstacles stand your way. Only by rebuilding your massive collection of ''80s VHS tapes, cassettes and video games will you be able to save the day. So pop your collar, fluff your mullet and lace your kicks... It''s time for Super 80s World, dude. Nothing but cool synthwave tunes and tasty waves lie ahead. Time to see if you can outrun the ''80s!' FROM games WHERE igdb_id = 116013 ON CONFLICT (game_id, language_code) DO NOTHING;
