INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Story Beside', 'Step into the shoes of Lyric, the humble innkeeper in a quiet mountain village, as she reflects upon a lifetime of poignant memories, heartwarming friendships, and bittersweet choices — proving along the way that you don''t have to slay dragons to be the hero of your own story.' FROM games WHERE igdb_id = 110710 ON CONFLICT (game_id, language_code) DO NOTHING;
