INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crimson Hotel', 'In 1949 two gruesome accidents tainted the Crimson''s reputation and led to an innocent mother being charged with murder. Jane Barker hasn''t been seen since her release in 1954. You''re a group of teenagers on their way home from a party when your car breaks down outside the Crimson Hotel...' FROM games WHERE igdb_id = 121645 ON CONFLICT (game_id, language_code) DO NOTHING;
