INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anne Frank House VR', 'In 1942, during the Second World War, Anne Frank, a thirteen-year-old Jewish girl and her family were forced to go into hiding to escape persecution from the Nazis. For more than two years, the Franks and 4 others would live in the “Secret Annex” of an old office building in Amsterdam, sharing the burden of living in hiding in confined quarters with the constant threat of discovery.
