INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evkworld', '体验无需编程的全能游戏编辑器：唤境引擎！唤境引擎提供了多种游戏类型所需的常用逻辑，从物理碰撞到自动寻路均可一键配置，同时也提供自由编写游戏逻辑的能力；支持多种素材格式，从精灵到骨骼再到tilemap，也支持PC、安卓、H5等多个平台的打包发布；更有丰富的教程、示例、模板、手册来帮你快速上手。' FROM games WHERE igdb_id = 120379 ON CONFLICT (game_id, language_code) DO NOTHING;
