INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jigsaw-masterpieces', 147951, '2019-03-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co599n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbuy.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jigsaw Masterpieces', 'Many convenient functions for completing the puzzle, such as the function to separate edge and inner pieces and the auto save function for playing lighthearted at any time. - a Cavalier King Charles Spaniel Dog and an American Shorthair Cat - Saint Isaac''s Cathedral - The Dolomites in Italy Play with the above three different pictures that have three different piece sizes: large, medium, and small. And a lot of DLC is releasing, such as beautiful landscape of the world, masterpieces of painting, popular cartoon characters, dogs and cats. You will surely find the your best puzzle! If it is a digital jigsaw puzzle... You don''t have to worry about losing the pieces. You don''t have to need prepare a large space to suspend the puzzle. Let''s have fun playing the jigsaw puzzle with "Jigsaw Masterpieces"! Features: -Easy-to-play traditional jigsaw puzzle -Selection of six background colors -For each jigsaw puzzle, 3 difficulty levels can be set -Separate edge and inner pieces -Ability to snap individual pieces together -Auto save -More puzzles will increase with DLC' FROM games WHERE igdb_id = 147951 ON CONFLICT (game_id, language_code) DO NOTHING;
