INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The World Next Door', 'The World Next Door is a narrative-driven, action adventure game that follows Jun, a rebellious teen girl trapped in a parallel world inhabited by magical creatures. Inspired by the emotional storytelling and thrilling action of both anime and indie games, players can expect to meet and develop friendships with an eclectic cast of characters while uncovering the mysteries hidden within this world.' FROM games WHERE igdb_id = 86457 ON CONFLICT (game_id, language_code) DO NOTHING;
