INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Royale', 'Tiny Royale is a top-down multiplayer shooter that reinvents the battle royale experience for the Snapchat platform. Tiny Royale lets players choose custom characters and squad up with friends or battle solo for quick two-minute rounds to loot and shoot their way to victory. Up to 30 players can battle at a time, forming squads of up to four friends. As players progress they can unlock characters and collect weapons and health packs while the map shrinks during the match until only one player, or team, remains.' FROM games WHERE igdb_id = 119240 ON CONFLICT (game_id, language_code) DO NOTHING;
