INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supermarket Shriek', 'Supermarket Shriek is a unique (shopping) kart racer where an unlikely duo (a man and a goat) find themselves in a trolley, navigating through various obstacle courses and challenges situated inside a range of shops, boutiques and supermarkets. Because, why not? Furthermore, movement is controlled by our hero’s voice, or more specifically, their wild incomprehensible screaming. Propel our protagonists using a gamepad in single player or play our unique co-op mode with dual microphones for an experience like no other!' FROM games WHERE igdb_id = 107170 ON CONFLICT (game_id, language_code) DO NOTHING;
