INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vanguard: Normandy 1944', 'Lead your team to victory by suppressing the enemy and using squad-based tactics to win the fight. With its real-world battlefields and painstakingly recreated weapons, equipment and uniforms all rendered in the stunning CryEngine, Vanguard: Normandy 1944 challenges players to fight and secure historic WWII objectives during the most ferocious and intense battle of modern history: D-Day.' FROM games WHERE igdb_id = 110298 ON CONFLICT (game_id, language_code) DO NOTHING;
