INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scrap Rush!!', 'SCRAP RUSH!! puts you and your friends into an arena full of metal blocks that might remind you of classics like Bomberman. Instead of bombs, you collect scrap, turn it into blocks, launch them in straight lines to crush your opponents between them and the wall to grab their scrap while dodging other players'' attacks! Depending on the game mode, last robot standing or the one with the most scrap wins.' FROM games WHERE igdb_id = 113588 ON CONFLICT (game_id, language_code) DO NOTHING;
