INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oik Memory: Endgame', 'Oik Memory: Endgame is a great way to experience your memory! At each level, from 1 to 9 cubes are disguised, the arrangement of which you need to remember. At first, you just need to memorize where the necessary elements are, but with each new level the game begins to throw a new challenge to the player: the cubes begin to move around the stage, mix and even spin in a circle!' FROM games WHERE igdb_id = 118623 ON CONFLICT (game_id, language_code) DO NOTHING;
