INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Degrees of Separation', 'Degrees of Separation is a puzzle platformer where cooperation is built into every move. Two contrasting souls, Ember and Rime, fall in love, but are separated by an enigmatic force, and must use their powers to progress through a spectacular world of fantasy and adventure. Players solve environmental obstacles by drawing upon the contrasting temperatures of warm and cold in single-player and cooperative multiplayer.' FROM games WHERE igdb_id = 110503 ON CONFLICT (game_id, language_code) DO NOTHING;
