INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Out of the Park Baseball 20', 'Officially licensed by MLB, MiLB and the MLBPA, OOTP 20 is a baseball fan''s dream come true and the only game ever to win the Metacritic PC Game of the Year Award twice. Step into the shoes of a GM and/or manager to own the future or rewrite the past of your favorite real-world baseball franchise. Build the team the way you want. Start a new career with your favorite 2019 MLB team or go back through almost 150 years of baseball history and run any team from the past! You can even set up your own fictional baseball universe.' FROM games WHERE igdb_id = 115688 ON CONFLICT (game_id, language_code) DO NOTHING;
