INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle for Gaming', 'With this one time price you get not only full access to our shop, our Lootboxes our DLC management system and our Live Services, but you also get the base game! We want that the player feels pride and accomplishment from getting upgrades from DLCs, Lootboxes and Live Services. But no worries, all in-game purchases are just there for player choices and are only cosmetic (excluded are all pay-to-win upgrades).' FROM games WHERE igdb_id = 110081 ON CONFLICT (game_id, language_code) DO NOTHING;
