INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stranded Sails', 'Stranded Sails is an open world farming adventure full of discoveries, quests and puzzles! Along with your crew you are ship-wrecked on a mysterious archipelago. Now it''s up to you to secure your survival and solve the mysteries deep in the heart of the islands –and finally escape.' FROM games WHERE igdb_id = 112344 ON CONFLICT (game_id, language_code) DO NOTHING;
